def calculate_unit_weights(distribution):
    # Calculate the sum of all values
    total_sum = sum(distribution.values())

    # Normalize the distribution to get unit weights
    unit_weights = {key: value / total_sum for key, value in distribution.items()}

    return unit_weights


def calculate_task_arrival_rate(key_weights, total_sum, parallelism, sorted_keys):
    """
    Calculate task arrival rates based on key weights and parallelism.

    Parameters:
        key_weights (dict): Dictionary of key arrival rate weights.
        total_sum (float): Sum of all key arrival rates.
        parallelism (int): Number of parallel tasks.
        sorted_keys (list): List of keys sorted by their arrival rates.

    Returns:
        dict: Task arrival rates.
    """
    # Normalize key weights to calculate key arrival rates
    key_arrival_rates = {key: (weight * total_sum) for key, weight in key_weights.items()}

    # Initialize task arrival rates
    tasks = [f"task_{i}" for i in range(parallelism)]
    task_arrival_rates = {task: 0 for task in tasks}

    n = len(sorted_keys)  # Total number of keys

    # Assign keys to tasks and calculate arrival rates
    for j in range(parallelism):
        start = (j * n + parallelism - 1) // parallelism
        end = ((j + 1) * n - 1) // parallelism

        for key_index in range(start, end + 1):
            key = sorted_keys[key_index]
            task_arrival_rates[tasks[j]] += key_arrival_rates[key]

    return task_arrival_rates


